let projectId=localStorage.getItem('behiveProjectId');
let questions=[];
let rootNode=null;
let selectedQuestion=null;
let dialogMode='add';
const findings=[];
let library=[];
let bibliography=[];
let discovery={nodes:[],edges:[],frontiers:[],hypotheses:[],cycles:[],active:false};
let frontierPanel='frontiers';
const graphZoomers={};
let evolution={versions:[],experiments:[],events:[],audits:[]};
let deepAnalysis=null;
let researchGaps=[];
let analysisRevisions=[];
let gapPollTimer=null;
let architectureDraft=null;
let architectProgressTimer=null;
const agents=[['PL','Planner','Ranking research frontier','ACTIVE'],['SC','Scout','Searching sources','ACTIVE'],['VR','Verifier','Checking claims','ACTIVE'],['CN','Connector','Mapping cross-thread links','IDLE']];
const $=selector=>document.querySelector(selector);
const investigationDlg=$('#investigationDialog');
function escapeHtml(value){const div=document.createElement('div');div.textContent=value??'';return div.innerHTML}
async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.detail||data.message||`Request failed (${response.status})`);return data}
async function ensureProject(){
 if(projectId){
  try{await loadTree();return}
  catch(error){localStorage.removeItem('behiveProjectId');projectId=null;rootNode=null;selectedQuestion=null}
 }
 try{
  const created=await api('/projects',{method:'POST',body:JSON.stringify({title:$('#projectTitle').textContent.trim(),root_question:$('#rootQuestion').textContent.trim(),cadence_minutes:1440})});
  projectId=created.id;localStorage.setItem('behiveProjectId',projectId);await loadTree();
 }catch(error){$('#missionMessage').textContent=`Project storage unavailable: ${error.message}`}
}
async function loadTree(){
 const data=await api(`/projects/${projectId}/map`);const nodes=data.nodes||[];
 rootNode=nodes.find(n=>n.type==='question'&&!n.parent_id)||null;
 questions=nodes.filter(n=>n.type==='question'&&n.parent_id&&n.status!=='archived').map(n=>({id:n.id,parentId:n.parent_id,title:n.label,depth:n.depth,confidence:Math.round((n.confidence||0)*100),findings:0,kind:(n.kind||'followup').toUpperCase(),priority:n.priority,status:n.status}));
 findings.splice(0,findings.length,...nodes.filter(n=>n.type==='finding').map(f=>({time:'SAVED FINDING',score:Math.round((f.confidence||0)*100),text:f.label,source:f.source_url||'Source pending'})));
 if(rootNode){$('#rootQuestion').textContent=rootNode.label;$('#rootTreeTitle').textContent=rootNode.label;$('#rootTreeMeta').textContent=`${Math.round((rootNode.confidence||0)*100)}% confidence · priority ${Math.round((rootNode.priority||1)*100)}%`;$('#projectTitle').textContent=rootNode.label.length>42?rootNode.label.slice(0,39)+'…':rootNode.label}
 await loadFrontier();
 render();
}
async function loadFrontier(){try{const data=await api(`/projects/${projectId}/frontier?limit=1`);const item=data.frontier?.[0];$('#frontierTitle').textContent=item?.question||'No frontier ranked yet';$('#frontierMeta').textContent=item?`Discovery score ${Math.round((item.score||0)*100)}%`:'Add questions or start research to rank the next thread.'}catch(error){$('#frontierTitle').textContent='Frontier unavailable';$('#frontierMeta').textContent=error.message}}
function render(){
 $('#questionTree').innerHTML=questions.sort((a,b)=>a.depth-b.depth||b.priority-a.priority).map(q=>`<div class="branch" style="margin-left:${Math.max(0,q.depth-1)*24}px"><span class="node"></span><div class="question-card ${selectedQuestion?.id===q.id?'selected':''}" data-id="${q.id}"><span class="tag">${escapeHtml(q.kind)} · ${escapeHtml(q.status)}</span><h3>${escapeHtml(q.title)}</h3><div class="bar"><i style="width:${q.confidence}%"></i></div><small>${q.confidence}% confidence · priority ${Math.round(q.priority*100)}%</small></div></div>`).join('')||'<p class="sub">Select Add question to create the first branch.</p>';
 $('#findingFeed').innerHTML=findings.map(f=>`<article class="finding"><div class="meta"><span>${escapeHtml(f.time)}</span><span class="confidence">${f.score}% confidence</span></div><p>${escapeHtml(f.text)}</p><a href="${f.source?.startsWith('http')?escapeHtml(f.source):'#'}">${escapeHtml(f.source)} →</a></article>`).join('')||'<p class="sub">No findings yet. Verified findings will appear here as research progresses.</p>';
 const questionCount=questions.length+(rootNode?1:0),findingCount=findings.length,confidence=findingCount?Math.round(findings.reduce((sum,f)=>sum+f.score,0)/findingCount):0,coverage=questionCount?Math.round(questions.filter(q=>q.confidence>0).length/questionCount*100):0;
 $('#metricFindings').textContent=findingCount;$('#metricConfidence').textContent=findingCount?(confidence/100).toFixed(2):'—';$('#metricQuestions').textContent=questionCount;$('#navQuestionCount').textContent=questionCount;$('#navFindingCount').textContent=findingCount;$('#navLibraryCount').textContent=findings.filter(f=>f.source?.startsWith('http')).length;$('#navReviewCount').textContent=findings.length;$('#coverageValue').textContent=`${coverage}%`;$('#coverageBar').style.width=`${coverage}%`;$('#coverageNote').textContent=findingCount?`${questions.filter(q=>q.confidence===0).length} questions need evidence`:'No findings yet';
 $('#agents').innerHTML=agents.map(a=>`<div class="agent"><span class="avatar">${a[0]}</span><div><b>${a[1]}</b><small>${a[2]}</small></div><span>${a[3]}</span></div>`).join('');
 document.querySelectorAll('#questionTree .question-card').forEach(card=>{card.onclick=()=>selectQuestion(card.dataset.id);card.ondblclick=()=>openEdit()});
 $('#editQuestion').disabled=!selectedQuestion;drawGraph();
}
function selectQuestion(id){selectedQuestion=questions.find(q=>q.id===id)||null;$('#rootTreeCard').classList.remove('selected');render();$('#addQuestion').textContent=selectedQuestion?'＋ Add child':'＋ Add question'}
async function selectRoot(){if(!rootNode)await ensureProject();if(!rootNode){$('#missionMessage').textContent='The root question could not be loaded. Check database health and refresh.';return}selectedQuestion={id:rootNode.id,title:rootNode.label,depth:0,confidence:Math.round((rootNode.confidence||0)*100),findings:0,kind:'ROOT',priority:rootNode.priority||1,status:rootNode.status||'open',isRoot:true};$('#rootTreeCard').classList.add('selected');render();$('#rootTreeCard').classList.add('selected');$('#addQuestion').textContent='＋ Add child'}
function drawGraph(){const svg=$('#graphSvg');const shown=questions.slice(0,4);let nodes=[{x:450,y:70,t:'Root question',c:'#215b43'}];shown.forEach((q,i)=>nodes.push({x:150+i*200,y:230,t:q.kind,c:'#6989bd'}));findings.slice(0,shown.length).forEach((f,i)=>nodes.push({x:150+i*200,y:410,t:f.score+'% finding',c:'#d99b35'}));let lines=shown.map((_,i)=>`<line x1="450" y1="70" x2="${150+i*200}" y2="230"/>`).join('')+findings.slice(0,shown.length).map((_,i)=>`<line x1="${150+i*200}" y1="230" x2="${150+i*200}" y2="410"/>`).join('');svg.innerHTML=`<g stroke="#c7d0c8" stroke-width="2">${lines}</g>`+nodes.map(n=>`<g><circle cx="${n.x}" cy="${n.y}" r="18" fill="${n.c}"/><text x="${n.x}" y="${n.y+34}" text-anchor="middle" font-size="11" fill="#34443b">${escapeHtml(n.t)}</text></g>`).join('')}
function makeGraphZoomer(svgId,baseBox){const svg=$('#'+svgId);if(!svg)return null;const host=svg.closest('.graph-zoom-host'),readout=host.querySelector('.graph-zoom-readout'),base={...baseBox},state={...baseBox,drag:null,moved:false};const clamp=()=>{state.w=Math.max(base.w*.16,Math.min(base.w*2,state.w));state.h=state.w*(base.h/base.w);state.x=Math.max(base.x-base.w*.5,Math.min(base.x+base.w*1.5-state.w,state.x));state.y=Math.max(base.y-base.h*.5,Math.min(base.y+base.h*1.5-state.h,state.y))};const apply=()=>{clamp();svg.setAttribute('viewBox',`${state.x} ${state.y} ${state.w} ${state.h}`);readout.textContent=`${Math.round(base.w/state.w*100)}%`};const zoom=(factor,cx=state.x+state.w/2,cy=state.y+state.h/2)=>{const oldW=state.w,oldH=state.h;state.w*=factor;state.h*=factor;state.x=cx-(cx-state.x)*(state.w/oldW);state.y=cy-(cy-state.y)*(state.h/oldH);apply()};host.querySelector('.graph-tools').onclick=event=>{const action=event.target.closest('[data-graph-action]')?.dataset.graphAction;if(!action)return;if(action==='zoom-in')zoom(.75);else if(action==='zoom-out')zoom(1.333);else if(action==='fit'){Object.assign(state,base);apply()}else if(action==='expand'){const expanded=host.classList.toggle('graph-expanded');document.body.classList.toggle('graph-expanded-open',expanded);event.target.textContent=expanded?'Close':'Expand';setTimeout(apply,0)}};svg.addEventListener('wheel',event=>{event.preventDefault();const rect=svg.getBoundingClientRect(),cx=state.x+(event.clientX-rect.left)/rect.width*state.w,cy=state.y+(event.clientY-rect.top)/rect.height*state.h;zoom(event.deltaY<0?.82:1.22,cx,cy)},{passive:false});svg.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('[data-node-id],[data-edge-id]'))return;state.drag={x:event.clientX,y:event.clientY,startX:state.x,startY:state.y};state.moved=false;host.classList.add('is-panning');svg.setPointerCapture(event.pointerId)});svg.addEventListener('pointermove',event=>{if(!state.drag)return;const rect=svg.getBoundingClientRect(),dx=event.clientX-state.drag.x,dy=event.clientY-state.drag.y;if(Math.abs(dx)+Math.abs(dy)>3)state.moved=true;state.x=state.drag.startX-dx/rect.width*state.w;state.y=state.drag.startY-dy/rect.height*state.h;apply()});const end=event=>{if(!state.drag)return;state.drag=null;host.classList.remove('is-panning');try{svg.releasePointerCapture(event.pointerId)}catch(_){}};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);svg.addEventListener('click',event=>{if(state.moved){event.preventDefault();event.stopImmediatePropagation();state.moved=false}},true);apply();return{zoom,fit:()=>{Object.assign(state,base);apply()},state,host}}
graphZoomers.evidence=makeGraphZoomer('graphSvg',{x:0,y:0,w:900,h:520});graphZoomers.discovery=makeGraphZoomer('discoverySvg',{x:0,y:0,w:1000,h:650});document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;Object.values(graphZoomers).forEach(control=>{if(control?.host.classList.contains('graph-expanded')){control.host.classList.remove('graph-expanded');control.host.querySelector('[data-graph-action="expand"]').textContent='Expand'}});document.body.classList.remove('graph-expanded-open')});
async function loadDiscovery(){if(!activeMission)return;try{discovery=await api(`/research/${activeMission}/discovery`);renderDiscovery()}catch(error){$('#discoverySummary').textContent=`Discovery map unavailable: ${error.message}`} }
function scoreChips(scores={}){return ['novelty','testability','impact'].map(k=>`<span>${k} ${Math.round((Number(scores[k])||0)*100)}%</span>`).join('')}
function renderFrontierRail(){const rail=$('#frontierRail');if(frontierPanel==='hypotheses'){rail.innerHTML=(discovery.hypotheses||[]).map(h=>`<article class="hypothesis-card"><div class="frontier-meta"><span>${escapeHtml(h.type)}</span><b>${Math.round((Number(h.scores?.priority)||0)*100)} priority</b></div><h3>${escapeHtml(h.name)}</h3><p>${escapeHtml(h.statement)}</p><div class="score-row">${scoreChips(h.scores)}</div><details><summary>Predictions and discriminators</summary><b>Observable predictions</b><ul>${(h.predictions||[]).map(x=>`<li>${escapeHtml(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul><b>Discriminating tests</b><ul>${(h.discriminators||[]).map(x=>`<li>${escapeHtml(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul><b>Missing links</b><ul>${(h.missing_links||[]).map(x=>`<li>${escapeHtml(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul></details></article>`).join('')||'<div class="empty-frontier">No hypothesis portfolio yet.</div>'}else{rail.innerHTML=(discovery.frontiers||[]).map(f=>`<article class="frontier-card"><div class="frontier-meta"><span>${escapeHtml(f.type)} · ${escapeHtml(f.absence_type)}</span><b>${Math.round((Number(f.priority)||0)*100)}</b></div><h3>${escapeHtml(f.title)}</h3><p>${escapeHtml(f.rationale)}</p><div class="score-row">${scoreChips(f.scores)}</div></article>`).join('')||'<div class="empty-frontier">Run a discovery cycle to locate meaningful unknowns.</div>'}}
function renderDiscovery(){const nodes=(discovery.nodes||[]).slice(0,70),edges=(discovery.edges||[]).filter(e=>nodes.some(n=>n.id===e.source)&&nodes.some(n=>n.id===e.target)).slice(0,120),svg=$('#discoverySvg');const positions={};nodes.forEach((n,i)=>{const ring=i<12?150:i<35?245:315,angle=(i*2.399963229728653)+(i%4)*.13;positions[n.id]={x:500+Math.cos(angle)*ring,y:325+Math.sin(angle)*ring}});const edgeMarkup=edges.map(e=>{const a=positions[e.source],b=positions[e.target];if(!a||!b)return'';return `<g data-edge-id="${escapeHtml(e.id)}"><line class="graph-edge ${escapeHtml(e.state)}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><line class="graph-edge-hit" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"><title>Open ${escapeHtml(e.relation)} evidence</title></line></g>`}).join('');const colors={compound:'#7b68a7',receptor:'#537eaa',pathway:'#467a62',cell_type:'#6c9472',disease:'#b45b4c',phenotype:'#bd8637',observation:'#d99b35',process:'#4f826f',measurement:'#798a97',condition:'#9a8664'};const nodeMarkup=nodes.map(n=>{const p=positions[n.id],label=n.label.length>28?n.label.slice(0,26)+'…':n.label;return `<g class="discovery-node" data-node-id="${escapeHtml(n.id)}"><circle cx="${p.x}" cy="${p.y}" r="${n.state==='observed'?12:9}" fill="${colors[n.type]||'#6989bd'}"><title>Open ${escapeHtml(n.label)}</title></circle><text x="${p.x}" y="${p.y+23}" text-anchor="middle">${escapeHtml(label)}</text></g>`}).join('');svg.innerHTML=`<circle cx="500" cy="325" r="82" fill="#e5eddf" stroke="#215b43"/><text x="500" y="320" text-anchor="middle" font-size="13" font-weight="700">EXPLORATORY PROBE</text><text x="500" y="342" text-anchor="middle" font-size="10">click any point or connection</text>${edgeMarkup}${nodeMarkup}`;const cycle=discovery.cycles?.[0];$('#discoverySummary').textContent=`${nodes.length} mapped concepts · ${edges.length} evidence relationships · ${discovery.frontiers?.length||0} open frontiers · ${discovery.hypotheses?.length||0} competing hypotheses${cycle?` · cycle ${cycle.number} ${cycle.status}`:''}`;$('#metricFindings').textContent=nodes.length;$('#metricConfidence').textContent=discovery.frontiers?.length||0;renderFrontierRail()}
async function showDiscovery(){if(!activeMission){missionMessage.textContent='Start or reopen a probe before mapping its frontier.';return}$('.shell').classList.add('discovery-mode');$('#workspace').classList.add('hidden');$('#graphView').classList.add('hidden');$('#collectionView').classList.add('hidden');$('#discoveryView').classList.remove('hidden');await loadDiscovery()}
document.querySelectorAll('[data-frontier-panel]').forEach(button=>button.onclick=()=>{frontierPanel=button.dataset.frontierPanel;document.querySelectorAll('[data-frontier-panel]').forEach(b=>b.classList.toggle('active',b===button));renderFrontierRail()});
$('#runDiscovery').onclick=async()=>{if(!activeMission)return;const button=$('#runDiscovery');button.disabled=true;button.textContent='Mapping frontier…';try{await api(`/research/${activeMission}/discovery/cycles`,{method:'POST'});for(let i=0;i<45;i++){await new Promise(r=>setTimeout(r,3000));await loadDiscovery();if(!discovery.active)break}}catch(error){missionMessage.textContent=`Discovery cycle failed: ${error.message}`}finally{button.disabled=false;button.textContent='Run discovery cycle'}};

async function loadEvolution(){if(!activeMission)return;try{evolution=await api(`/research/${activeMission}/evolution`);renderLabRail()}catch(error){$('#discoverySummary').textContent=`Evolution unavailable: ${error.message}`}}
function listItems(items){return `<ul>${(items||[]).map(x=>`<li>${escapeHtml(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul>`}
function renderLabRail(){if(['frontiers','hypotheses'].includes(frontierPanel)){renderFrontierRail();return}const rail=$('#frontierRail');if(frontierPanel==='evolution'){rail.innerHTML=(evolution.versions||[]).map(v=>`<article class="hypothesis-card ${v.survivor?'survivor':'dominated'}"><div class="frontier-meta"><span>G${v.generation} · ${escapeHtml(v.operator)}</span><b>${v.survivor?'PARETO SURVIVOR':'DOMINATED'}</b></div><h3>${escapeHtml(v.name)}</h3><p>${escapeHtml(v.statement)}</p><div class="plausibility"><i style="width:${Math.round((Number(v.posterior)||0)*100)}%"></i></div><small>Plausibility ${Math.round((Number(v.prior)||0)*100)}% → ${Math.round((Number(v.posterior)||0)*100)}% · utility ${Math.round((Number(v.scores?.utility)||0)*100)}%</small><details><summary>Graph, predictions, and assumptions</summary><b>Predictions</b>${listItems(v.predictions)}<b>Discriminators</b>${listItems(v.discriminators)}<b>Assumptions</b>${listItems(v.assumptions)}<b>Safety</b>${listItems(v.safety_risks)}</details></article>`).join('')||'<div class="empty-frontier">No evolved generations yet.</div>'}else if(frontierPanel==='experiments'){rail.innerHTML=(evolution.experiments||[]).map(x=>`<article class="frontier-card experiment-card"><div class="frontier-meta"><span>${escapeHtml(x.type)} · ${escapeHtml(x.status)}</span><b>UTILITY ${Math.round((Number(x.utility)||0)*100)}</b></div><h3>${escapeHtml(x.title)}</h3><p>${escapeHtml(x.description)}</p><div class="score-row"><span>info ${Math.round((Number(x.information_gain)||0)*100)}%</span><span>feasible ${Math.round((Number(x.feasibility)||0)*100)}%</span><span>cost ${Math.round((Number(x.cost)||0)*100)}%</span></div><details><summary>Outcomes and required data</summary><b>Possible outcomes</b>${listItems(x.outcomes)}<b>Required data</b>${listItems(x.required_data)}</details></article>`).join('')||'<div class="empty-frontier">No discriminating tests ranked yet.</div>'}else if(frontierPanel==='timeline'){rail.innerHTML=(evolution.events||[]).map(x=>`<article class="frontier-card timeline-card"><div class="frontier-meta"><span>${escapeHtml(x.type)}</span><b>${escapeHtml(String(x.created_at||''))}</b></div><h3>${escapeHtml(x.subject_type)} ${escapeHtml(x.subject_id||'population')}</h3><p>${escapeHtml(x.reason||'Graph state changed')}</p></article>`).join('')||'<div class="empty-frontier">No evolution events yet.</div>'}else{rail.innerHTML=(evolution.audits||[]).map(x=>`<article class="frontier-card audit-card"><div class="frontier-meta"><span>${escapeHtml(x.severity)} · ${escapeHtml(x.type)}</span><b>${escapeHtml(x.status)}</b></div><h3>${escapeHtml(x.message)}</h3><p>${escapeHtml(x.remediation||'')}</p></article>`).join('')||'<div class="empty-frontier">Graph audit found no open quality problems.</div>'}}
async function showDiscoveryLab(){if(!activeMission){missionMessage.textContent='Start or reopen a probe before opening the Discovery Laboratory.';return}$('.shell').classList.add('discovery-mode');$('#workspace').classList.add('hidden');$('#graphView').classList.add('hidden');$('#collectionView').classList.add('hidden');$('#discoveryView').classList.remove('hidden');await Promise.all([loadDiscovery(),loadEvolution()])}
async function evolvePopulation(){if(!activeMission)return;const button=$('#evolveHypotheses');button.disabled=true;button.textContent='Evolving…';try{const result=await api(`/research/${activeMission}/evolution/generations`,{method:'POST'});missionMessage.textContent=`Generation ${result.generation}: ${result.versions} variants, ${result.survivors} Pareto survivors, ${result.experiments} tests`;frontierPanel='evolution';document.querySelectorAll('[data-frontier-panel]').forEach(b=>b.classList.toggle('active',b.dataset.frontierPanel==='evolution'));await loadEvolution()}catch(error){missionMessage.textContent=`Evolution failed: ${error.message}`}finally{button.disabled=false;button.textContent='Evolve hypotheses'}}
$('#evolveHypotheses').onclick=evolvePopulation;

function contextHtml(value){const entries=Object.entries(value||{});return entries.length?`<div class="context-grid">${entries.map(([k,v])=>`<b>${escapeHtml(k)}</b><span>${escapeHtml(Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):v)}</span>`).join('')}</div>`:'<p>No experimental context was recorded.</p>'}
function inspectorShell(title,state,body){$('#frontierRail').innerHTML=`<div class="map-inspector"><div class="inspector-head"><button class="inspector-back" data-inspector-back>← Back to ${escapeHtml(frontierPanel)}</button><div class="inspector-state">${escapeHtml(state||'')}</div><h3>${escapeHtml(title)}</h3></div>${body}</div>`}
function connectionButton(edge,node){return `<button class="connection-row" data-inspect-edge="${escapeHtml(edge.id)}"><span>${escapeHtml(node?.label||'Unknown')} · ${escapeHtml(edge.relation)}</span><b>${escapeHtml(edge.state)}</b></button>`}
function inspectNode(nodeId){const node=discovery.nodes.find(n=>n.id===nodeId);if(!node)return;const connected=discovery.edges.filter(e=>e.source===nodeId||e.target===nodeId),sources=[...new Set(connected.map(e=>e.evidence_url).filter(Boolean))],frontiers=discovery.frontiers.filter(f=>f.source===nodeId||f.target===nodeId),hypotheses=discovery.hypotheses.filter(h=>(h.path_nodes||[]).some(x=>x===nodeId||String(x).toLowerCase()===node.label.toLowerCase()));inspectorShell(node.label,`${node.type} · ${node.state}`,`<section class="inspector-section"><h4>Meaning in this map</h4><p>${escapeHtml(node.description||'No description was extracted.')}</p></section><section class="inspector-section"><h4>Recorded context</h4>${contextHtml(node.context)}</section><section class="inspector-section"><h4>Connected evidence (${connected.length})</h4>${connected.map(e=>connectionButton(e,discovery.nodes.find(n=>n.id===(e.source===nodeId?e.target:e.source)))).join('')||'<p>No explicit edges.</p>'}</section><section class="inspector-section"><h4>Underlying sources (${sources.length})</h4>${sources.map(url=>`<a class="inspector-link" href="${escapeHtml(url)}" target="_blank" rel="noopener">Open gathered evidence ↗<br>${escapeHtml(url)}</a>`).join('')||'<p>No direct source attached; treat this point as an organizing concept.</p>'}</section><section class="inspector-section"><h4>Open frontiers and ideas</h4>${frontiers.map(f=>`<button class="connection-row" data-inspect-frontier="${escapeHtml(f.id)}"><span>${escapeHtml(f.title)}</span><b>${escapeHtml(f.absence_type)}</b></button>`).join('')}${hypotheses.map(h=>`<button class="connection-row" data-inspect-seed="${escapeHtml(h.id)}"><span>${escapeHtml(h.name)}</span><b>hypothesis</b></button>`).join('')||(!frontiers.length?'<p>No hypothesis path currently references this point.</p>':'')}</section>`) }
function inspectEdge(edgeId){const edge=discovery.edges.find(e=>e.id===edgeId);if(!edge)return;const source=discovery.nodes.find(n=>n.id===edge.source),target=discovery.nodes.find(n=>n.id===edge.target);inspectorShell(`${source?.label||'Unknown'} → ${target?.label||'Unknown'}`,`${edge.relation} · ${edge.state} · ${Math.round((Number(edge.confidence)||0)*100)}%`,`<section class="inspector-section"><h4>Relationship</h4><button class="connection-row" data-inspect-node="${escapeHtml(edge.source)}"><span>${escapeHtml(source?.label||edge.source)}</span><b>source point</b></button><button class="connection-row" data-inspect-node="${escapeHtml(edge.target)}"><span>${escapeHtml(target?.label||edge.target)}</span><b>target point</b></button></section><section class="inspector-section"><h4>Underlying evidence</h4><div class="evidence-quote">${escapeHtml(edge.excerpt||'No supporting excerpt was stored.')}</div>${edge.evidence_url?`<a class="inspector-link" href="${escapeHtml(edge.evidence_url)}" target="_blank" rel="noopener">Open original gathered source ↗<br>${escapeHtml(edge.evidence_url)}</a>`:'<p>No source URL: this relationship must not be treated as observed evidence.</p>'}</section><section class="inspector-section"><h4>Conditions and boundaries</h4>${contextHtml(edge.conditions)}</section><section class="inspector-section inspector-actions"><button data-counterfactual="${escapeHtml(edge.id)}">What if this connection is false?</button></section>`)}
function inspectFrontier(id){const f=discovery.frontiers.find(x=>x.id===id);if(!f)return;inspectorShell(f.title,`${f.type} · ${f.absence_type} · priority ${Math.round((Number(f.priority)||0)*100)}%`,`<section class="inspector-section"><h4>Why this is a frontier</h4><p>${escapeHtml(f.rationale)}</p></section><section class="inspector-section"><h4>Search and validation strategy</h4>${contextHtml(f.search_strategy)}</section><section class="inspector-section"><h4>Frontier scores</h4>${contextHtml(f.scores)}</section>${f.source?`<button class="connection-row" data-inspect-node="${escapeHtml(f.source)}"><span>Open source-side concept</span><b>map point</b></button>`:''}${f.target?`<button class="connection-row" data-inspect-node="${escapeHtml(f.target)}"><span>Open target-side concept</span><b>map point</b></button>`:''}`)}
