$('#discoverySvg').onclick=event=>{const node=event.target.closest('[data-node-id]'),edge=event.target.closest('[data-edge-id]');if(node)inspectNode(node.dataset.nodeId);else if(edge)inspectEdge(edge.dataset.edgeId)};
