function renderArchitectureDraft(){const a=architectureDraft?.architecture;if(!a)return;$('#architectEmpty').hidden=true;$('#architectResult').hidden=false;$('#architectRoot').textContent=a.root_question;$('#architectScope').textContent=a.scope||'No additional scope boundaries supplied.';$('#architectNotes').innerHTML=(a.reframing_notes||[]).map(note=>`<p>↳ ${escapeHtml(note)}</p>`).join('')+(a.assumptions||[]).map(note=>`<p class="assumption">Assumption: ${escapeHtml(note)}</p>`).join('');$('#architectTree').innerHTML=(a.questions||[]).map(q=>`<article style="margin-left:${Math.max(0,q.depth-1)*24}px"><div><span>${escapeHtml(q.kind)} · P${Math.round(q.priority*100)}</span><b>${escapeHtml(q.question)}</b><small>${escapeHtml(q.rationale)}</small><em>Evidence: ${escapeHtml(q.evidence_target)}</em></div></article>`).join('')}
$('#generateArchitecture').onclick=async()=>{const button=$('#generateArchitecture'),brain_dump=$('#architectDump').value.trim();if(brain_dump.length<15){$('#architectStatus').textContent='Add more detail first';$('#architectStatusDetail').textContent='Give the architect at least one complete sentence.';return}button.disabled=true;button.textContent='Architecting…';architectureDraft=null;$('#architectResult').hidden=true;$('#architectEmpty').hidden=false;$('#architectEmpty').classList.add('working');$('#architectLoader').hidden=false;$('#architectSpark').textContent='✦';const started=Date.now(),stages=['Reading your intent and boundaries','Reframing the main research question','Building analytical branches','Adding counterevidence and validation paths','Checking hierarchy and evidence targets'];let stage=0;$('#architectStatus').textContent=stages[0];$('#architectStatusDetail').textContent='AI question design usually takes 30–60 seconds · 0s elapsed';architectProgressTimer=setInterval(()=>{const elapsed=Math.floor((Date.now()-started)/1000);stage=Math.min(stages.length-1,Math.floor(elapsed/9));$('#architectStatus').textContent=stages[stage];$('#architectStatusDetail').textContent=`Working · ${elapsed}s elapsed · your current tree is unchanged`},1000);const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),90000);try{await ensureProject();architectureDraft=await api(`/projects/${projectId}/question-architect`,{method:'POST',signal:controller.signal,body:JSON.stringify({brain_dump,max_depth:Number($('#architectDepth').value),max_questions:Number($('#architectCount').value)})});renderArchitectureDraft()}catch(error){$('#architectEmpty').hidden=false;$('#architectStatus').textContent=error.name==='AbortError'?'Question design timed out':'Question Architect could not finish';$('#architectStatusDetail').textContent=error.name==='AbortError'?'Try again with a shorter subject or fewer questions.':error.message;missionMessage.textContent=`Question Architect failed: ${error.message}`}finally{clearTimeout(timeout);if(architectProgressTimer){clearInterval(architectProgressTimer);architectProgressTimer=null}$('#architectEmpty').classList.remove('working');$('#architectLoader').hidden=true;button.disabled=false;button.textContent='Generate question tree'}};
async function applyArchitecture(mode){if(!architectureDraft)return;const button=mode==='replace'?$('#replaceArchitecture'):$('#mergeArchitecture');button.disabled=true;try{await api(`/projects/${projectId}/question-architect/apply`,{method:'POST',body:JSON.stringify({architecture_id:architectureDraft.id,mode})});architectDlg.close();selectedQuestion=null;await loadTree();missionMessage.textContent=`AI question tree ${mode==='replace'?'replaced':'merged'} successfully.`}catch(error){missionMessage.textContent=`Could not apply AI tree: ${error.message}`}finally{button.disabled=false}}
