function resetInvestigationState(){if(missionTimer){clearInterval(missionTimer);missionTimer=null}if(gapPollTimer){clearTimeout(gapPollTimer);gapPollTimer=null}activeMission=null;coreTelemetry={signature:'',lastChange:Date.now(),data:null};findings.splice(0);library=[];bibliography=[];deepAnalysis=null;researchGaps=[];analysisRevisions=[];rootNode=null;questions=[];selectedQuestion=null;toggle.disabled=false;toggle.textContent='Start research';runStatus.textContent='Agents paused';renderCoreMonitor();render()}
