async function createNewInvestigation(useArchitect){const subject=$('#newProjectSubject').value.trim();if(subject.length<8){missionMessage.textContent='Enter a main subject or research question of at least 8 characters.';return}const title=$('#newProjectTitle').value.trim()||subject.replace(/\s+/g,' ').slice(0,90);const button=useArchitect?$('#createAndShape'):$('#createInvestigation');button.disabled=true;try{const created=await api('/projects',{method:'POST',body:JSON.stringify({title,root_question:subject.slice(0,2000),cadence_minutes:1440})});projectId=created.id;localStorage.setItem('behiveProjectId',projectId);localStorage.setItem(`behiveProjectInitialized:${projectId}`,'1');localStorage.removeItem(`behiveMission:${projectId}`);resetInvestigationState();investigationDlg.close();await loadTree();missionMessage.textContent='New investigation created. Refine the tree or start research.';if(useArchitect){$('#openArchitect').click();$('#architectDump').value=subject}}catch(error){missionMessage.textContent=`Could not create investigation: ${error.message}`}finally{button.disabled=false}}
