const toggle=$('#toggleRun'),runStatus=$('#runStatus'),missionMessage=$('#missionMessage');let activeMission=null,missionTimer=null;
const coreDefs=[['Plan','planning','Build research plan'],['Scout','scout','Discover sources'],['Harvest','harvest','Retrieve source content'],['Extract','process','Extract claims'],['Verify','falsify','Challenge evidence'],['Analyze','analyze','Compare mechanisms and scenarios'],['Synthesize','synth','Build conclusions'],['Connect','graph','Link knowledge graph']];
let coreTelemetry={signature:'',lastChange:Date.now(),data:null};
function effectiveCore(data){const names=coreDefs.map(c=>c[1]);const values=[data?.phase,data?.status].map(v=>(v||'').toLowerCase());let index=-1;values.forEach(v=>names.forEach((name,i)=>{if(v.includes(name))index=Math.max(index,i)}));if(values.includes('done')||values.includes('insufficient'))return names.length;return index<0?0:index}
function renderCoreMonitor(data=null){
 const count=data?.claims_so_far??data?.claims_count??0,status=(data?.status||'idle').toLowerCase(),activeIndex=effectiveCore(data),terminal=['done','insufficient','error','cancelled','interrupted'].includes(status),serverFailed=data?.watchdog?.state==='fail',stalled=!terminal&&activeMission&&(serverFailed||Date.now()-coreTelemetry.lastChange>180000);
 let summaryState='waiting',summary='No active mission',heartbeat='Waiting to start';
 if(activeMission){summaryState=['error','cancelled','interrupted'].includes(status)||serverFailed?'failed':status==='insufficient'?'no-results':status==='done'?(count?'complete':'no-results'):stalled?'stalled':'working';summary=['error','cancelled','interrupted'].includes(status)?`Research ${status}`:serverFailed?'Mission integrity failure':status==='insufficient'?'Complete · insufficient evidence':status==='done'?(count?`Complete · ${count} findings`:'Complete · no results'):stalled?'No progress detected':`${coreDefs[Math.min(activeIndex,coreDefs.length-1)][0]} core churning`;heartbeat=status==='insufficient'?'The retrieved material could not support defensible claims':serverFailed?'One or more watchdog tests failed':stalled?'No phase or finding change for 3+ minutes':`Last progress ${Math.max(0,Math.floor((Date.now()-coreTelemetry.lastChange)/1000))}s ago`}
 $('#coreSummaryDot').className=`core-state-dot ${summaryState}`;$('#coreSummary').textContent=summary;$('#coreHeartbeat').textContent=heartbeat;
 $('#coreGrid').innerHTML=coreDefs.map((core,i)=>{let state='waiting',label='Waiting';if(activeMission){if((status==='error'||serverFailed)&&i===activeIndex){state='failed';label='Failed'}else if(status==='done'||status==='insufficient'){state=count?'complete':(i>=3?'no-results':'complete');label=count?'Complete':(i>=3?'Insufficient':'Complete')}else if(i<activeIndex){state='complete';label='Complete'}else if(i===activeIndex){state=stalled?'stalled':'working';label=stalled?'No progress':'Churning'}}return `<div class="core-unit ${state}"><div class="core-unit-top"><b>${core[0]}</b><span class="core-unit-state">${label}</span></div><div class="activity-track"><i class="activity-bar"></i></div><small>${core[2]}</small></div>`}).join('');
 const checks=data?.watchdog?.checks||[{label:'Worker heartbeat',state:'unknown',detail:'No mission telemetry'},{label:'Phase consistency',state:'unknown',detail:'No mission telemetry'},{label:'Source-to-finding flow',state:'unknown',detail:'No mission telemetry'},{label:'Result production',state:'unknown',detail:'No mission telemetry'},{label:'Full mission completion',state:'unknown',detail:'No mission telemetry'}];
 $('#watchdogTests').innerHTML=checks.map(test=>`<div class="watchdog-test ${escapeHtml(test.state)}"><i></i><b>${escapeHtml(test.label)}</b><small>${escapeHtml(test.detail)}</small></div>`).join('');
 const failedCheck=checks.find(test=>test.state==='fail'),diagnostics=data?.diagnostics||{},failureStage=diagnostics.failure_stage||data?.phase||'last durable',attempt=Number(diagnostics.recovery_attempt||0),checkpoint=`${data?.sources_so_far||0} sources · ${data?.documents_so_far||0} documents · ${data?.claims_so_far||0} findings`;$('#recoveryControl').hidden=!(activeMission&&failedCheck);if(failedCheck)$('#recoveryReason').textContent=diagnostics.error_message?`${failureStage} failed: ${diagnostics.error_message}. Checkpoint preserved (${checkpoint}). ${attempt?`Previous recovery attempts: ${attempt}.`:''}`:`Recover ${failureStage} from preserved checkpoint: ${checkpoint}`;
}
$('#recoverMission').onclick=async()=>{if(!activeMission)return;const button=$('#recoverMission');button.disabled=true;button.textContent='Starting recovery…';try{const result=await api(`/research/${activeMission}/recover`,{method:'POST'});localStorage.setItem('behiveActiveMission',activeMission);coreTelemetry={signature:'',lastChange:Date.now(),data:null};$('#recoveryReason').textContent=`Attempt ${result.attempt||1}: ${result.message||`resuming from ${result.recovery_stage}`}`;missionMessage.textContent='Recovery started with prior sources and documents preserved.';await pollMission();if(!missionTimer)missionTimer=setInterval(pollMission,3000)}catch(error){missionMessage.textContent=`Recovery failed to start: ${error.message}`}finally{button.disabled=false;button.textContent='Recover failed stage'}};
async function pollMission(){if(!activeMission){renderCoreMonitor();return}try{const data=await api(`/research/${activeMission}/status`);const count=data.claims_so_far??data.claims_count??data.total_claims??0,signature=`${data.status}|${data.phase}|${count}`;if(signature!==coreTelemetry.signature){coreTelemetry.signature=signature;coreTelemetry.lastChange=Date.now()}coreTelemetry.data={...data,claims_so_far:count};renderCoreMonitor(coreTelemetry.data);runStatus.textContent=`${data.phase||data.status} · ${count} findings`;missionMessage.textContent=`Mission ${activeMission} · ${data.status} · ${data.phase||'starting'}`;if(['done','insufficient','error','cancelled','interrupted'].includes(data.status)){clearInterval(missionTimer);missionTimer=null;localStorage.removeItem('behiveActiveMission');toggle.disabled=false;toggle.textContent='Start another';if(['done','insufficient'].includes(data.status))await loadMissionResults()}}catch(error){runStatus.textContent='Status unavailable';missionMessage.textContent=error.message;$('#coreSummaryDot').className='core-state-dot failed';$('#coreSummary').textContent='Monitor offline';$('#coreHeartbeat').textContent=error.message}}
async function loadMissionResults(){try{const data=await api(`/research/${activeMission}`);const claims=data.claims||[];findings.splice(0,findings.length,...claims.slice(0,20).map(c=>({time:'NEW FINDING',score:Math.round((c.confidence||c.quality_score||0)*100),text:c.text||c.claim,source:c.source_url||'Source pending'})));render();missionMessage.textContent=`Complete · ${claims.length} sourced findings available`}catch(error){missionMessage.textContent=`Research complete; results unavailable: ${error.message}`}}
async function loadEvidenceCollections(){if(!activeMission)return;try{const data=await api(`/research/${activeMission}/evidence`);library=data.library||[];bibliography=data.bibliography||[];$('#navLibraryCount').textContent=library.length}catch(error){missionMessage.textContent=`Evidence library unavailable: ${error.message}`}}
async function loadDeepAnalysis(){if(!activeMission)return;try{deepAnalysis=(await api(`/research/${activeMission}/analysis`)).analysis}catch(error){deepAnalysis=null}}
async function loadGapControls(){if(!activeMission)return;try{const [g,r]=await Promise.all([api(`/research/${activeMission}/gaps`),api(`/research/${activeMission}/analysis/revisions`)]);researchGaps=g.gaps||[];analysisRevisions=r.revisions||[]}catch(error){researchGaps=[];analysisRevisions=[]}}
function gapCards(){return researchGaps.map(g=>{const active=['queued','scouting','harvesting','extracting','evaluating'].includes(g.status),pct=Math.min(100,Math.round((g.full_text_sources/g.target_sources)*75+(g.primary_sources/g.target_primary)*25));return `<article class="gap-card ${escapeHtml(g.status)}" data-gap-id="${g.id}"><div class="gap-top"><span>P${g.priority} · ${escapeHtml(g.status.toUpperCase())}</span><b>${g.full_text_sources}/${g.target_sources} full text · ${g.primary_sources}/${g.target_primary} primary</b></div><h4>${escapeHtml(g.question)}</h4><div class="evidence-progress"><i style="width:${pct}%"></i></div><p>${escapeHtml(g.message)}</p><div class="gap-actions">${active?'<button data-gap-action="pause">Pause</button>':'<button class="deepen" data-gap-action="deepen">Deepen research</button>'}<button data-gap-action="edit">Edit search</button><button data-gap-action="dismiss">Dismiss</button></div></article>`}).join('')||'<div class="empty-state">No open Analyst research gaps.</div>'}
function revisionCards(){return analysisRevisions.map(r=>`<article class="revision"><b>${escapeHtml(r.reason)}</b><span>${escapeHtml(r.created_at)} · claims ${r.previous_claims} → ${r.new_claims} · depth ${escapeHtml(r.previous_depth||'none')} → ${escapeHtml(r.new_depth||'unknown')}</span></article>`).join('')||'<p class="sub">No evidence-driven analysis revisions yet.</p>'}
function analysisCards(){if(!deepAnalysis)return '<div class="analysis-empty">Deep analysis has not been generated for this mission.</div>';const a=deepAnalysis,rankings=(a.rankings||[]).map((r,i)=>`<tr><td><b>${i+1}. ${escapeHtml(r.subject)}</b></td><td>${escapeHtml(r.direction||'—')}</td><td>${'●'.repeat(Math.max(0,Math.min(5,Number(r.magnitude)||0)))}${'○'.repeat(5-Math.max(0,Math.min(5,Number(r.magnitude)||0)))}</td><td>${escapeHtml(r.horizon||'—')}</td><td>${Math.round((Number(r.confidence)||0)*100)}%</td><td>${escapeHtml(r.mechanism||'')}</td></tr>`).join('');const deductions=(a.deductions||[]).map(d=>`<article class="analysis-item hypothesis"><span>HYPOTHESIS · ${Math.round((Number(d.confidence)||0)*100)}%</span><h4>${escapeHtml(d.deduction)}</h4><p>${escapeHtml(d.reasoning||'')}</p></article>`).join('');const scenarios=(a.scenarios||[]).map(s=>`<article class="analysis-item"><span>SCENARIO · ${Math.round((Number(s.confidence)||0)*100)}%</span><h4>${escapeHtml(s.name)}</h4><p><b>Trigger:</b> ${escapeHtml(s.trigger||'')}</p><p>${escapeHtml(Array.isArray(s.expected_effects)?s.expected_effects.join('; '):s.expected_effects||'')}</p></article>`).join('');return `<section class="analysis-hero ${escapeHtml(a.depth_status||'insufficient')}"><div><span>ANALYST CORE · ${(a.depth_status||'insufficient').toUpperCase()} EVIDENCE</span><h3>Deeper analysis</h3><p>${escapeHtml(a.executive_assessment||'')}</p></div><div class="depth-badge">${escapeHtml(a.depth_status||'insufficient')}</div></section><h3 class="analysis-heading">Comparative ranking</h3><div class="analysis-table-wrap"><table class="analysis-table"><thead><tr><th>Product group</th><th>Effect</th><th>Magnitude</th><th>Horizon</th><th>Confidence</th><th>Causal mechanism</th></tr></thead><tbody>${rankings||'<tr><td colspan="6">Insufficient evidence to rank.</td></tr>'}</tbody></table></div><div class="analysis-columns"><div><h3 class="analysis-heading">Scenario analysis</h3>${scenarios||'<p class="sub">No scenarios generated.</p>'}</div><div><h3 class="analysis-heading">Novel deductions</h3>${deductions||'<p class="sub">No defensible deductions yet.</p>'}</div></div><h3 class="analysis-heading">Targeted evidence acquisition</h3><div class="evidence-gate">Analysis-ready requires <b>3 independent full-text sources</b>, including <b>1 primary source</b>. Search snippets remain discovery records only.</div><div class="gap-grid">${gapCards()}</div><h3 class="analysis-heading">Analysis revision history</h3><div class="revision-list">${revisionCards()}</div><h3 class="analysis-heading">Limitations</h3><ul class="limitation-list">${(a.limitations||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`}
function findingCards(){return analysisCards()+`<h3 class="analysis-heading sourced-heading">Sourced findings</h3>`+(findings.map((f,i)=>`<article class="result-card"><div class="result-kicker"><span>Finding ${i+1}</span><b>${f.score}% confidence</b></div><h3>${escapeHtml(f.text)}</h3>${f.source?.startsWith('http')?`<a href="${escapeHtml(f.source)}" target="_blank" rel="noopener">Open supporting source ↗</a>`:'<span class="sub">Source pending</span>'}</article>`).join('')||'<div class="empty-state">No findings are available for this mission yet.</div>')}
function libraryCards(){return library.map((item,i)=>{const trust=[item.evidence_tier?`Tier ${item.evidence_tier}`:'Unranked',item.verification_status==='registry_verified'?'Registry verified':'Unverified',item.is_primary?'Primary record':'',item.is_open_access?'Open access':''].filter(Boolean).join(' · ');return `<article class="source-card"><div class="source-index">${String(i+1).padStart(2,'0')}</div><div><div class="result-kicker"><span>${escapeHtml(item.domain||'Source')}</span><b>${escapeHtml(trust)}</b></div><h3>${escapeHtml(item.title)}</h3><p>${item.word_count} words · ${escapeHtml(item.harvest_method)} · quality ${Math.round(item.quality_score*100)}%${item.persistent_id?` · ${escapeHtml(item.persistent_id)}`:''}</p><a href="${escapeHtml(item.url)}" target="_blank" rel="noopener">Open source ↗</a></div></article>`}).join('')||'<div class="empty-state">No harvested documents are available yet.</div>'}
function bibliographyRows(){return bibliography.map(item=>`<li><span class="bib-number">${item.number}.</span><div>${item.author?`${escapeHtml(item.author)}. `:''}<cite>${escapeHtml(item.title)}</cite>. ${item.published_date?`${escapeHtml(item.published_date)}. `:''}<a href="${escapeHtml(item.url)}" target="_blank" rel="noopener">${escapeHtml(item.domain||item.url)}</a>${item.persistent_id?` <small>${escapeHtml(item.persistent_id)}</small>`:''}${item.verification_status==='registry_verified'?` <b>Registry verified · Tier ${item.evidence_tier||'—'}${item.is_primary?' · Primary record':''}.</b>`:''}${item.supports_findings?` <b>Supports ${item.supports_findings} finding${item.supports_findings===1?'':'s'}.</b>`:''}</div></li>`).join('')||'<div class="empty-state">No bibliography entries are available yet.</div>'}
async function showView(view){if(view!=='graph')$('.shell').classList.remove('discovery-mode');if(gapPollTimer){clearTimeout(gapPollTimer);gapPollTimer=null}document.querySelectorAll('nav button[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===view));const graph=view==='graph',overview=['overview','questions'].includes(view);$('#workspace').classList.toggle('hidden',!overview);$('#graphView').classList.toggle('hidden',!graph);$('#collectionView').classList.toggle('hidden',overview||graph);if(['findings','library','bibliography'].includes(view)){await loadEvidenceCollections();if(view==='findings'){await Promise.all([loadDeepAnalysis(),loadGapControls()])}const config={findings:['FINDINGS + ANALYSIS','Research findings',`${findings.length} evidence-linked findings with analytical interpretation`,findingCards()],library:['SOURCE LIBRARY','Research library',`${library.length} recovered or harvested documents`,libraryCards()],bibliography:['BIBLIOGRAPHY','Sources and citations',`${bibliography.length} unique sources`,`<ol class="bibliography-list">${bibliographyRows()}</ol>`]}[view];$('#collectionEyebrow').textContent=config[0];$('#collectionTitle').textContent=config[1];$('#collectionSummary').textContent=config[2];$('#collectionBody').innerHTML=config[3];if(view==='findings'&&researchGaps.some(g=>['queued','scouting','harvesting','extracting','evaluating'].includes(g.status)))gapPollTimer=setTimeout(()=>showView('findings'),5000)}}
document.querySelectorAll('nav button[data-view]').forEach(button=>button.onclick=()=>showView(button.dataset.view));
$('#collectionBody').onclick=async event=>{const button=event.target.closest('[data-gap-action]');if(!button||!activeMission)return;const card=button.closest('[data-gap-id]'),gapId=card?.dataset.gapId,action=button.dataset.gapAction;if(!gapId)return;button.disabled=true;try{if(action==='edit'){const current=researchGaps.find(g=>String(g.id)===String(gapId));const question=window.prompt('Edit targeted research question',current?.question||'');if(!question){button.disabled=false;return}await api(`/research/${activeMission}/gaps/${gapId}`,{method:'PATCH',body:JSON.stringify({question})})}else await api(`/research/${activeMission}/gaps/${gapId}/${action}`,{method:'POST'});await showView('findings')}catch(error){missionMessage.textContent=`Gap action failed: ${error.message}`;button.disabled=false}};
toggle.onclick=async()=>{const question=$('#rootQuestion').textContent.trim();if(question.length<8){missionMessage.textContent='Enter a research question of at least 8 characters.';return}toggle.disabled=true;toggle.textContent='Starting…';runStatus.textContent='Starting research';try{await ensureProject();const data=await api('/research',{method:'POST',body:JSON.stringify({query:question,depth:3,scale:30})});activeMission=data.job_id||data.mission_id;localStorage.setItem('behiveActiveMission',activeMission);localStorage.setItem(`behiveMission:${projectId}`,activeMission);localStorage.setItem(`behiveProjectInitialized:${projectId}`,'1');coreTelemetry={signature:'',lastChange:Date.now(),data:null};toggle.textContent='Research running';await pollMission();missionTimer=setInterval(pollMission,3000)}catch(error){toggle.disabled=false;toggle.textContent='Start research';runStatus.textContent='Could not start';missionMessage.textContent=error.message}};
['budget','maxAgents'].forEach(id=>$('#'+id).oninput=e=>$('#'+id.replace('maxAgents','agents')+'Out').textContent=e.target.value);$('#autonomy').onchange=e=>$('#autonomyBadge').textContent=e.target.value.toUpperCase();$('#savePolicy').onclick=async e=>{try{await ensureProject();await api(`/projects/${projectId}/policy`,{method:'PUT',body:JSON.stringify({autonomy:$('#autonomy').value,status:'paused',daily_budget:Number($('#budget').value),max_agents:Number($('#maxAgents').value),max_depth:5,min_confidence:.7,primary_sources_required:true,approval_new_branches:true,freshness_days:30})});e.target.textContent='Saved ✓'}catch(error){missionMessage.textContent=error.message}setTimeout(()=>e.target.textContent='Save policy',1300)};
async function resumeActiveResearch(){try{const initialized=localStorage.getItem(`behiveProjectInitialized:${projectId}`)==='1',saved=localStorage.getItem(`behiveMission:${projectId}`);const data=await api('/missions?limit=40');const missions=(data.missions||[]).filter(m=>!String(m.id||'').startsWith('gap_'));let mission=saved?missions.find(m=>m.id===saved):null;if(!mission&&!initialized&&rootNode)mission=missions.find(m=>String(m.topic||'').trim().toLowerCase()===String(rootNode.label||'').trim().toLowerCase())||missions[0];if(!mission){activeMission=null;toggle.disabled=false;toggle.textContent='Start research';renderCoreMonitor();return}activeMission=mission.id;localStorage.setItem(`behiveMission:${projectId}`,activeMission);localStorage.setItem(`behiveProjectInitialized:${projectId}`,'1');toggle.disabled=true;toggle.textContent='Research running';await pollMission();if(!['done','insufficient','error','cancelled','interrupted'].includes(mission.status)&&!missionTimer)missionTimer=setInterval(pollMission,3000)}catch(error){renderCoreMonitor()}}
async function bootstrap(){render();renderCoreMonitor();await ensureProject();await resumeActiveResearch()}
bootstrap();
document.querySelectorAll('button[data-view="graph"]').forEach(button=>button.onclick=showDiscoveryLab);
document.querySelectorAll('button[data-panel="graph"]').forEach(button=>button.onclick=showDiscoveryLab);
document.querySelectorAll('button[data-view]:not([data-view="graph"]),button[data-panel]:not([data-panel="graph"])').forEach(button=>button.addEventListener('click',()=>{$('#discoveryView').classList.add('hidden');$('.shell').classList.remove('discovery-mode')}));
document.querySelectorAll('[data-frontier-panel]').forEach(button=>button.onclick=()=>{frontierPanel=button.dataset.frontierPanel;document.querySelectorAll('[data-frontier-panel]').forEach(b=>b.classList.toggle('active',b===button));renderLabRail()});
